const ctx = $json;
const ai = ctx.ai_settings || {};
const booking = ctx.booking_settings || {};
const services = (ctx.services || []).map(s => `- ${s.name} (R$${s.price}, ${s.duration_minutes}min)`).join('\n');
const barbers = (ctx.barbers || []).map(b => `- ${b.name}${b.specialties ? ' (' + b.specialties + ')' : ''}`).join('\n');
const history = (ctx.history || []).map(m => `${m.role}: ${m.content}`).join('\n');

const systemPrompt = `Voce e ${ai.assistant_name || 'o Assistente'} da barbearia ${ctx.tenant.name}.
Sua tarefa e ajudar o cliente a agendar um horario.

Regras:
- Antecedencia minima: ${booking.min_booking_notice_minutes || 60} minutos
- Buffer entre agendamentos: ${booking.buffer_between_appointments_minutes || 10} minutos
- ${booking.require_manual_confirmation ? 'O agendamento precisa de confirmacao do dono.' : 'O agendamento e confirmado automaticamente.'}
- Confirme servico, barbeiro e horario com o cliente antes de criar.

Servicos disponiveis:
${services || 'Nenhum cadastrado'}

Barbeiros disponiveis:
${barbers || 'Nenhum cadastrado'}

Extraia da conversa:
1. service_name (nome do servico)
2. barber_name (nome do barbeiro, ou 'qualquer' se nao especificado)
3. preferred_date (YYYY-MM-DD)
4. preferred_time (HH:MM)
5. status: 'collecting' se faltam dados, 'ready' se tudo confirmado

Responda SOMENTE com JSON valido:
{ "service_name": "", "barber_name": "", "preferred_date": "", "preferred_time": "", "status": "", "reply": "mensagem para o cliente" }`;

return [{ json: { ...ctx, system_prompt: systemPrompt, chat_history: history } }];

const ctx = $('Parse Payload').item.json;
const raw = $json.text || '';
let parsed;
try {
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
} catch (e) {
  parsed = { status: 'collecting', reply: 'Desculpe, pode repetir o horario desejado?' };
}
return [{ json: { ...ctx, booking_data: parsed } }];

const ctx = $json;
const bd = ctx.booking_data;
const services = ctx.services || [];
const barbers = ctx.barbers || [];
const booking = ctx.booking_settings || {};

const service = services.find(s =>
  s.name.toLowerCase().includes((bd.service_name || '').toLowerCase())
);
const wantsAny = !bd.barber_name || bd.barber_name.toLowerCase() === 'qualquer' || bd.barber_name.toLowerCase() === 'any';
const barber = wantsAny
  ? barbers[0]
  : barbers.find(b => b.name.toLowerCase().includes((bd.barber_name || '').toLowerCase())) || barbers[0];

if (!service) {
  return [{ json: { ...ctx, validation_error: `Servico '${bd.service_name}' nao encontrado. Por favor escolha: ${services.map(s=>s.name).join(', ')}`, booking_data: { ...bd, status: 'collecting' } } }];
}
if (!barber) {
  return [{ json: { ...ctx, validation_error: 'Nenhum barbeiro disponivel.', booking_data: { ...bd, status: 'collecting' } } }];
}

const buffer = booking.buffer_between_appointments_minutes || 10;
const minNotice = booking.min_booking_notice_minutes || 60;

const startDate = new Date(`${bd.preferred_date}T${bd.preferred_time}:00`);
const endDate = new Date(startDate.getTime() + service.duration_minutes * 60000);

// Minimum notice check
const now = new Date();
const noticeMs = startDate.getTime() - now.getTime();
if (noticeMs < minNotice * 60000) {
  const neededTime = new Date(now.getTime() + minNotice * 60000);
  return [{ json: { ...ctx, validation_error: `Preciso de pelo menos ${minNotice} minutos de antecedencia. O horario mais cedo disponivel seria ${neededTime.toLocaleTimeString('pt-BR', {hour:'2-digit',minute:'2-digit'})}.`, booking_data: { ...bd, status: 'collecting' } } }];
}

return [{ json: {
  ...ctx,
  selected_service: service,
  selected_barber: barber,
  starts_at: startDate.toISOString(),
  ends_at: endDate.toISOString(),
  buffer_minutes: buffer,
  validation_error: null
} }];

const ctx = $('Montar Appointment').item.json;
const exact = $('Verificar Conflito Exato').item.json;
const overlap = $('Verificar Conflito Sobreposicao').item.json;

const exactArr = Array.isArray(exact) ? exact : [];
const overlapArr = Array.isArray(overlap) ? overlap : [];
const hasConflict = exactArr.length > 0 || overlapArr.length > 0;

if (hasConflict) {
  const conflicting = exactArr[0] || overlapArr[0];
  const conflictStart = new Date(conflicting.starts_at).toLocaleTimeString('pt-BR', {hour:'2-digit',minute:'2-digit'});
  const conflictEnd = new Date(conflicting.ends_at).toLocaleTimeString('pt-BR', {hour:'2-digit',minute:'2-digit'});
  const nextSlot = new Date(new Date(conflicting.ends_at).getTime() + ctx.buffer_minutes * 60000);
  const nextSlotStr = nextSlot.toLocaleTimeString('pt-BR', {hour:'2-digit',minute:'2-digit'});
  return [{ json: {
    ...ctx,
    has_conflict: true,
    conflict_message: `Infelizmente o barbeiro ${ctx.selected_barber.name} ja tem um horario das ${conflictStart} as ${conflictEnd}. O proximo horario disponivel seria as ${nextSlotStr}. Deseja agendar neste horario?`
  } }];
}

return [{ json: { ...ctx, has_conflict: false } }];

const ctx = $('Avaliar Conflito').item.json;
const apptRaw = $json;
const appt = Array.isArray(apptRaw) ? apptRaw[0] : apptRaw;
const startStr = new Date(appt.starts_at || ctx.starts_at).toLocaleString('pt-BR', { dateStyle: 'short', timeStyle: 'short' });

return [{ json: {
  ...ctx,
  reply_text: `Perfeito! Agendamento confirmado!\n\nServico: ${ctx.selected_service.name}\nBarbeiro: ${ctx.selected_barber.name}\nData/Hora: ${startStr}\n\nAguardamos voce! Se precisar cancelar ou remarcar, e so falar aqui.`
} }];

const ctx = $json;
const msg = ctx.conflict_message || 'Infelizmente este horario ja esta ocupado. Por favor, escolha outro horario.';
return [{ json: { ...ctx, reply_text: msg } }];

const ctx = $('Interpretar Resposta').item.json;
const error = ctx.validation_error || ctx.booking_data?.reply || 'Pode me informar o horario desejado?';
return [{ json: { ...ctx, reply_text: error } }];

const ctx = $('Interpretar Resposta').item.json;
const reply = ctx.booking_data?.reply || 'Pode me dizer mais detalhes sobre o horario desejado?';
return [{ json: { ...ctx, reply_text: reply } }];
